// Renderiza slides via renderer HTTP API
const http = require('http');

const RENDERER_HOST = 'renderer';
const RENDERER_PORT = 3000;

const body   = $input.first().json.body || $input.first().json;
const pid    = body.production_id;
const scenes = body.scenes || [];

if (!scenes.length) throw new Error('scenes[] is required');

function httpPost(host, port, path, payload) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(payload);
    const options = {
      hostname: host, port, path,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
    };
    const req = http.request(options, res => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(body)); } catch(e) { resolve({ raw: body }); }
      });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

const results = [];
for (let i = 0; i < scenes.length; i++) {
  const props = scenes[i];
  const outputName = `${pid}-slide-${i}.mp4`;
  console.log(`[${pid}] Rendering slide ${i}: ${props.layout}`);
  const r = await httpPost(RENDERER_HOST, RENDERER_PORT, '/render', { props, output: outputName });
  if (r.error) throw new Error(`Slide ${i} error: ${r.error}`);
  console.log(`[${pid}] Slide ${i} done: ${r.path}`);
  results.push(r);
}

return [{ json: { production_id: pid, slide_count: results.length, slides: results.map((r, i) => ({ index: i, path: r.path, url: r.url })) } }];
